SELECT SUM(pa.Policy_Amount) AS total_premium
FROM policy_amount pa
JOIN premium p ON pa.Policy_Amount_Identifier = p.Policy_Amount_Identifier;

SELECT AVG(DATEDIFF('day', Claim_Open_Date, Claim_Close_Date)) AS avg_days_to_close
FROM claim
WHERE Claim_Open_Date IS NOT NULL AND Claim_Close_Date IS NOT NULL;

SELECT COUNT(*) AS claims_with_fireplace
FROM fire_claim
WHERE LOWER(TRIM(Fireplace)) IN ('yes', 'y', 'true', '1');

SELECT SUM(ca.Claim_Amount) AS total_loss_reserves
FROM loss_reserve lr
JOIN claim_amount ca ON lr.Claim_Amount_Identifier = ca.Claim_Amount_Identifier;
